B.Wd=new A.Z(B.w,["Nova City. Uma cidade onde humanos e rob\xf4s vivem juntos, em paz... tudo gra\xe7as \xe0 energia do N\xfacleo Nova.","Nova City. A city where humans and robots live together in peace... all thanks to the energy of the Nova Core.","Nova City. Una ciudad donde humanos y robots viven juntos, en paz... todo gracias a la energ\xeda del N\xfacleo Nova."],t.w)
B.alU=new A.e9(null,B.Wd,null)
B.Wb=new A.Z(B.w,["Olha s\xf3 esse c\xe9u! Dia perfeito pra treinar. Nada pode estragar isso... n\xe9, Zek?","Look at that sky! A perfect day to train. Nothing can ruin this... right, Zek?","\xa1Mira ese cielo! Un d\xeda perfecto para entrenar. Nada puede arruinarlo... \xbfverdad, Zek?"],t.w)
B.alL=new A.e9("kael",B.Wb,"happy")
B.W3=new A.Z(B.w,["Ai, n\xe3o! Por que voc\xea foi falar isso, Kael? Toda vez que algu\xe9m fala isso, d\xe1 tudo errado!","Oh, no! Why did you say that, Kael? Every time someone says that, everything goes wrong!","\xa1Ay, no! \xbfPor qu\xe9 dijiste eso, Kael? \xa1Cada vez que alguien lo dice, todo sale mal!"],t.w)
B.alV=new A.e9("zek",B.W3,"scared")
B.VU=new A.Z(B.w,["Relaxa, Zek! O que poderia acontecer?","Relax, Zek! What could possibly happen?","\xa1Tranquilo, Zek! \xbfQu\xe9 podr\xeda pasar?"],t.w)
B.alJ=new A.e9("kael",B.VU,"happy")
B.T1=s([B.alU,B.alL,B.alV,B.alJ],t.tG)
B.am0=new A.lJ("intro_1.jpg",1.05,1.18,B.dQ,B.eU,B.T1)
B.Ww=new A.Z(B.w,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.alO=new A.e9("luna",B.Ww,"scared")
B.Wp=new A.Z(B.w,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.alP=new A.e9("mira",B.Wp,"shocked")
B.W1=new A.Z(B.w,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.alT=new A.e9(null,B.W1,null)
B.Qx=s([B.alO,B.alP,B.alT],t.tG)
B.alY=new A.lJ("intro_2.jpg",1.05,1.18,B.br,B.aX,B.Qx)
B.Wc=new A.Z(B.w,["Ha ha ha ha! Povo de Nova City... a energia do N\xfacleo Nova agora pertence a MIM!","Ha ha ha ha! People of Nova City... the energy of the Nova Core now belongs to ME!","\xa1Ja ja ja ja! Pueblo de Nova City... \xa1la energ\xeda del N\xfacleo Nova ahora me pertenece a M\xcd!"],t.w)
B.alG=new A.e9("emperor",B.Wc,"laugh")
B.We=new A.Z(B.w,["Meus nove chefes v\xe3o guard\xe1-la pelo mundo inteiro. E voc\xeas, heroizinhos... v\xe3o passar uma temporada nas minhas c\xe1psulas!","My nine bosses will guard it all over the world. And you, little heroes... will spend some time in my capsules!","Mis nueve jefes la guardar\xe1n por todo el mundo. Y ustedes, hero\xedtos... \xa1pasar\xe1n una temporada en mis c\xe1psulas!"],t.w)
B.alH=new A.e9("emperor",B.We,null)
B.VW=new A.Z(B.w,["Isso \xe9 o que voc\xea pensa!","That's what you think!","\xa1Eso es lo que t\xfa crees!"],t.w)
B.alK=new A.e9("kael",B.VW,"angry")
B.QN=s([B.alG,B.alH,B.alK],t.tG)
B.alZ=new A.lJ("intro_3.jpg",1.25,1.05,B.k,B.k,B.QN)
B.VY=new A.Z(B.w,["Num instante, Luna, Mira, Zek e Nex foram levados... e trancados em c\xe1psulas, escondidas nas terras dos nove chefes.","In an instant, Luna, Mira, Zek and Nex were taken... and locked in capsules, hidden in the lands of the nine bosses.","En un instante, Luna, Mira, Zek y Nex fueron llevados... y encerrados en c\xe1psulas, escondidas en las tierras de los nueve jefes."],t.w)
B.alS=new A.e9(null,B.VY,null)
